 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 콤보설정
        scwin.setComboCode();
        $c.bns.BnsPanelToGroupBox(panel_1);

        // ui가리기
        lbl_unq1.hide();
        lbl_unq2.hide();
        lbl_unq3.hide();
        txb_UNQ_ISU_NM.hide();
        txb_UNQ_ISU_ENG_NM.hide();
        txb_SUPLY_FND_USE_RPT_RND_TP_CD.hide();

        // ui 조정.
        panel_2.style.top = 306;
        scwin.sriObjShow(true);
        scwin.suplyObjShow(false);
        scwin.sri_search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21900.onpageload" });
    }
};

