/**
 * @method
 * @name btn_Acpt_onclick
 * @description 「접수」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function() {
    try {
        // 체크된 것 카운팅
        let nTrueCnt = 0;
        let nFalseCnt = 0;
        for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                if (dts_List.getCellData(nRow, "STAT") !== "미처리") {
                    nFalseCnt++;
                }
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 정보가 없습니다.");
            return false;
        }
        if (nFalseCnt > 0) {
            await $c.win.alert("접수는 [미처리] 상태만 선택 할 수 있습니다.\n\n선택된 정보를 확인하세요.");
            return false;
        }
        scwin.sri_registerAll(nTrueCnt);
        // sri_register();    //asis
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21900.btn_Acpt_onclick" });
    }
};

