/**
 * @method
 * @name formCheck
 * @description 폼을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formCheck = async function() {
    if (scwin.p_SUPLY_YY === "N") {
        // 신규 접수 건
        if (!window.confirm("[" + txb_ISU_NM.getValue() + "]의 ESG채권 신청을 접수하시겠습니까? ")) {
            return false;
        } else {
            return 1;
        }
    } else {
        // 조달자금보고 최종이면서 미사용잔액 '0'인치 체크후 안내메세지
        if (txb_SUPLY_FND_USE_RPT_RND_TP_CD.getValue() === '3' && edt_UNUSED_AMT.getValue() !== '0') {
            await $c.win.alert("미사용잔액이 있습니다.");
        }
        if (window.confirm("[" + txb_ISU_NM.getValue() + "]의 " + txb_SUPLY_FND_USE_RPT_YY.getValue() + "년도 사후보고를 접수하시겠습니까? ")) {
            return 1;
        } else {
            return false;
        }
    }
};

