 */
scwin.formCheckTeamleadr = async function() {
    // 담당자는 팀장확인 안됨.
    if (js_jobtitl === '03') {
        await $c.win.alert('팀장권한만 가능합니다.');
        return false;
    } else {
        if (scwin.p_SUPLY_YY === "N") {
            // 신규 접수 건
            if (!window.confirm("[" + txb_ISU_NM.getValue() + "]의 ESG채권등록 신청을 팀장확인 하시겠습니까? ")) {
                return false;
