/**
 * @method
 * @name sri_detail
 * @description SRI 채권 신청 파일 조회
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.sri_detail = function(row) {
    // 데이터를 우선 지우고 신청ID가 없으면 스탑
    dts_detail.removeAll();
    if (row === "") {
        return;
    }
    scwin.p_APPL_SEQ = dts_List.getCellData(row, "APPL_ISU_SEQ");
    scwin.p_SRI_BND_TP_CD = cmb_SRI_BND_TP_CD.getValue();
    scwin.p_STD_CD = txb_STD_CD.getValue();
    let param = "&{P}V_APPL_ISU_SEQ=" + scwin.p_APPL_SEQ;
    param += "&{P}V_STD_CD=" + dts_List.getCellData(row, "STD_CD");
    let dsNm = 'BNSSRI_APPL_FILE_LIST';
    let qryId = 'lds.stf.bnssri.select.fileList';
    $c.bns.fn_SearchBns("ULDBNS21900.xml", dts_detail, dsNm, qryId, param);

    // 한글금액표기
    txb_AmtHan1.setValue($c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'ISU_AMT')));
    txb_AmtHan2.setValue($c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'SUPLY_FND_USE_RPT_EXECUTE_AMT')));
    txb_AmtHan3.setValue($c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'UNUSED_AMT')));
    txb_AmtHan4.setValue($c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'EXECUTE_AMT_SUM')));

    // 자금조달사용연도 기준으로 고유
    if (dts_List.getCellData(row, "SUPLY_FND_USE_RPT_YY") === "") {
        scwin.p_SUPLY_YY = "N";
        scwin.sriObjShow(true);
        scwin.suplyObjShow(false);
        txb_UNQ_ISU_NM.setReadOnly(true);
        txb_UNQ_ISU_ENG_NM.setReadOnly(true);
    } else {
        scwin.p_SUPLY_YY = "Y";
        scwin.sriObjShow(false);
        scwin.suplyObjShow(true);
    }
};

