/**
 * @method
 * @name setComboCode
 * @description 콤보데이터를 정의한다.
 * @returns {void}
 * @hidden N
 */
scwin.setComboCode = function() {
    // 기관코드
    let qryId = 'lds.stf.bnscommon.select.listInstCd';
    let dsNm = 'BNS_INST_INFO';
    let param = '&{P}V_INST_NM=';
    $c.bns.fn_SearchBns("ULDBNS21900.xml", dts_InstCd, dsNm, qryId, param);

    // 공통콤보
    $c.bns.fn_SetBnsCombo("ULDBNS21900.xml", dts_SRI_BND_TP_CD, 'SRI_BND_TP_CD'); // SRI채권구분
    $c.bns.fn_SetBnsCombo("ULDBNS21900.xml", dts_SRI_BND_REF_RULE_TP_CD, 'SRI_BND_REF_RULE_TP_CD'); // SRI채권준거원칙
    $c.bns.fn_SetBnsCombo("ULDBNS21900.xml", dts_EXT_REVW_INST_CD, 'EXT_REVW_INST_CD'); // 외부검토기관
    $c.bns.fn_SetBnsCombo("ULDBNS21900.xml", dts_SRI_BND_EXT_VALU_KIND_CD, 'SRI_BND_EXT_VALU_KIND_CD'); // 외부검토종류코드
    $c.bns.fn_SetBnsCombo("ULDBNS21900.xml", dts_CORE_OTCM_INDIC_CD, 'CORE_OTCM_INDIC_CD'); // KPI
    $c.bns.fn_SetBnsCombo("ULDBNS21900.xml", dts_SRI_BND_CHG_CONTN_CD, 'SRI_BND_CHG_CONTN_CD'); // 변경사항
    $c.bns.fn_SetBnsCombo("ULDBNS21900.xml", dts_SRI_BND_PROG_STAT_CD, 'SRI_BND_PROG_STAT_CD'); // 진행상태

    // 이것을 하지 않으면 그리드에서 코드와 명이 같이 보인다. 2022-07-19
    dts_CORE_OTCM_INDIC_CD.Reset();
    dts_SRI_BND_CHG_CONTN_CD.Reset();
    dts_SRI_BND_PROG_STAT_CD.Reset();
    dts_EXT_REVW_INST_CD.Reset();
};

/**
 * @method
 * @name fileDownload
 * @description 파일 다운로드
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function(row) {
    if (dts_detail.getCellData(row, "ORGN_FILE_NM") === "") {
        return;
    } else {
        let url = "/bns/BnsAttachDocFileDownload.do";
        url += "?ATTACH_FILE_TP_CD=" + 2;
        url += "&ISUR_CD=" + dts_detail.getCellData(row, "ISUR_CD");
        url += "&APPL_DD=" + dts_detail.getCellData(row, "APPL_DD");
        url += "&APPL_TM=" + dts_detail.getCellData(row, "APPL_TM");
        location.href = url;
    }
};

