/**
 * @method
 * @name setBtn
 * @description 버튼보이기를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setBtn = function() {
    const v_stat = dts_List.getCellData(dts_List.getRowPosition(), "STAT_CD");
    // alert(v_stat);

    if (v_stat === "0") {
        btn_Acpt.setBackgroundImage('../img/bns/btn_Acpt_n.gif');
        btn_Acpt.setDisabled(false);
        btn_ProcsComplt.setBackgroundImage('../img/bns/btn_20_d.gif');
        btn_ProcsComplt.setDisabled(true);
        btn_TeamleadrConfrm.setBackgroundImage('../img/bns/btn_21_d.gif');
        btn_TeamleadrConfrm.setDisabled(true);
    } else if (v_stat === "1") {
        btn_Acpt.setBackgroundImage('../img/bns/btn_Acpt_nd.gif');
        btn_Acpt.setDisabled(true);
        btn_ProcsComplt.setBackgroundImage('../img/bns/btn_20.gif');
        btn_ProcsComplt.setDisabled(false);
        btn_TeamleadrConfrm.setBackgroundImage('../img/bns/btn_21_d.gif');
        btn_TeamleadrConfrm.setDisabled(true);
    } else if (v_stat === "3") {
        btn_Acpt.setBackgroundImage('../img/bns/btn_Acpt_nd.gif');
        btn_Acpt.setDisabled(true);
        btn_ProcsComplt.setBackgroundImage('../img/bns/btn_20_d.gif');
        btn_ProcsComplt.setDisabled(true);
        btn_TeamleadrConfrm.setBackgroundImage('../img/bns/btn_21.gif');
        btn_TeamleadrConfrm.setDisabled(false);
    }
};

